# Generated by build.py from recipe.yml for recipe telnet-hold-a-line-session. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'session.txt'), "hello`nworld`nquit`n")
[IO.File]::WriteAllText((Join-Path $PWD 'loud.txt'), "one`nQUIT`nnever read`n")
[IO.File]::WriteAllText((Join-Path $PWD 'no-quit.txt'), "hello`n")
[IO.File]::WriteAllText((Join-Path $PWD 'long-line.txt'), "short`nthis line is far too long`nnever read`nquit`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', 'telnet://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -T session.txt telnet://127.0.0.1:8080/ } finally { Stop-Process $server0 }
